REQUIRED_IMPORTS = (
    "flask", "pandas", "numpy", "openpyxl", "rapidfuzz",
    "xlrd", "odf", "xlwt", "reportlab", "docx",
)


def main() -> int:
    options = sys.argv[1:]
    no_install = "--no-install" in options
    no_launch = "--no-launch" in options
    folders = [item for item in options if not item.startswith("--")]
    target = pathlib.Path(folders[0] if folders else "datafix_web").expanduser().resolve()

    if not target.exists():
        target.mkdir(parents=True)
    archive = base64.b64decode(PAYLOAD)
    with zipfile.ZipFile(io.BytesIO(archive)) as bundle:
        bundle.extractall(target)

    print("DataFix " + VERSION + " created in: " + str(target))
    print("Included deployment files: Procfile, render.yaml, railway.json")

    missing = [name for name in REQUIRED_IMPORTS if importlib.util.find_spec(name) is None]
    if missing and not no_install:
        print("Installing required packages (first run only)...")
        result = subprocess.run(
            [sys.executable, "-m", "pip", "install", "-r", "requirements.txt"],
            cwd=target,
        )
        if result.returncode != 0:
            print("Package installation failed. Run these commands manually:")
            print('  cd "' + str(target) + '"')
            print("  pip install -r requirements.txt")
            return result.returncode

    print("")
    print("Local start command:")
    print('  cd "' + str(target) + '"')
    print("  python app.py")
    print("Website: http://127.0.0.1:5000")
    print("Public deployment: push this folder to GitHub, then follow the Render steps.")

    if no_launch:
        return 0

    def open_browser() -> None:
        time.sleep(2)
        webbrowser.open("http://127.0.0.1:5000")

    threading.Thread(target=open_browser, daemon=True).start()
    try:
        return subprocess.call([sys.executable, "app.py"], cwd=target)
    except KeyboardInterrupt:
        return 0


if __name__ == "__main__":
    raise SystemExit(main())
if __name__ == "__main__":
    app.run(debug=True)